        max_depth = 0
        while stack:
            phi, depth = stack.pop()
            if not phi:
                continue
            if all(c == '0' or c == '1' for c in phi):
                max_depth = max(max_depth, depth)
                continue
            var = next(i for i, c in enumerate(phi) if c != '2')
