        n = len(phi)
        generators = []
        for i in range(n):
            if phi[i] != '2':
                continue
            new_phi = phi[:i] + '0' + phi[i+1:]
            if all(new_phi[j] == phi[j] or new_phi[j] == '2' for j in range(n)):
                generators.append(i)
        return len(generators)

